if($json.statusCode!==200)throw Error('Homewatch ledger unavailable; no billing should run.');
const s=$json.body;
const out=[];
for(const g of s.owner_groups||[]){
  const ready=(g.visits||[]).filter(v=>v.billing_status==='unbilled'&&v.property_id&&g.stripe_customer_id);
  const held=(g.visits||[]).filter(v=>v.billing_status==='held');
  if(held.length||!ready.length)continue;
  const invoiceLines=[];
  for(const v of ready){
    const label=new Date(v.visit_date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
    const note=v.notes?(' — '+v.notes):'';
    invoiceLines.push({
      description:`${label} — Homewatch Visit — ${v.property_address}${note}`,
      amountCents:Math.round(Number(v.visit_amount||0)*100),
      visitId:v.id,
      kind:'visit'
    });
    if(Number(v.other_charge||0)>0){
      invoiceLines.push({
        description:`${label} — ${v.other_charge_description||'Additional Homewatch charge'} — ${v.property_address}`,
        amountCents:Math.round(Number(v.other_charge||0)*100),
        visitId:v.id,
        kind:'other'
      });
    }
  }
  out.push({json:{
    month:s.month,
    ownerName:g.owner_name,
    stripeCustomerId:g.stripe_customer_id,
    visitIds:ready.map(v=>v.id),
    invoiceLines,
    amountCents:invoiceLines.reduce((n,line)=>n+line.amountCents,0),
    batchId:`hw:${s.month}:${g.stripe_customer_id}`
  }});
}
return out;
